  def dashboard_nav_link(label, path, icon: nil)
    active = current_page?(path)
    bg = active ? "background: rgba(49,38,59,0.06);" : ""
    fg = active ? "color: var(--color-eggplant);" : "color: var(--color-fg-1100);"

    link_to path, class: "flex items-center gap-3 px-3 py-2 text-sm font-medium rounded-lg transition-colors", style: "#{fg} #{bg}" do
      # SECURITY: raw() is safe here — SIDEBAR_ICONS is a frozen hash of hardcoded SVG path data.
      # Never pass user input as the icon key.
      icon_svg = if icon && SIDEBAR_ICONS[icon]
        raw('<svg class="w-5 h-5 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24">' + SIDEBAR_ICONS[icon] + '</svg>')
      end
      safe_join([ icon_svg, content_tag(:span, label) ].compact)
    end
  end
end
